def compute(vars):
    shares_thousand = vars["v1"]
    fair_value_per_share = vars["v2"]
    total_fair_value_thousand = shares_thousand * fair_value_per_share

    return {
        "value": total_fair_value_thousand,
        "trace": {
            "shares_thousand": shares_thousand,
            "fair_value_per_share": fair_value_per_share,
            "total_fair_value_thousand": total_fair_value_thousand,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": "currency"
            }
        }
    }
